const itemJson = $input.item.json || {};
const input = itemJson.body || itemJson.payload || itemJson;
const configs = itemJson.configs || input.configs || {};
const authUser = itemJson.user || {};
const userRole = String(authUser.role || 'admin').toLowerCase().trim();
const isUpdate = Boolean(input.id);

if (!isUpdate && userRole !== 'admin') {
  return {
    json: {
      valid: false,
      errorMessage: 'Acesso negado: apenas administradores podem cadastrar novas lojas.'
    }
  };
}

const nome = (input.nome || input.dadosDaLoja?.nome || '').trim();
if (!nome) {
  return {
    json: {
      valid: false,
      errorMessage: 'O nome da loja é obrigatório.'
    }
  };
}

const rawWhatsapp = (input.whatsapp_loja || input.dadosDaLoja?.whatsapp_loja || '').replace(/\D/g, '');
const whatsapp_loja = rawWhatsapp ? (rawWhatsapp.startsWith('55') ? rawWhatsapp : ('55' + rawWhatsapp)) : '';
const ativo = input.ativo !== undefined ? input.ativo : true;

// Monta dadosDaLoja
const dadosDaLoja = {
  nome: nome,
  whatsapp_loja: whatsapp_loja,
  email: input.dadosDaLoja?.email || '',
  site: input.dadosDaLoja?.site || '',
  endereco: input.dadosDaLoja?.endereco || '',
  linkGoogleMaps: input.dadosDaLoja?.linkGoogleMaps || '',
  instagram: input.dadosDaLoja?.instagram || '',
  facebook: input.dadosDaLoja?.facebook || '',
  horarioDeFuncionamento: input.dadosDaLoja?.horarioDeFuncionamento || {
    'seg-sex': '08:00 às 18:00',
    'sab': '08:00 às 12:00',
    'domingo': 'Fechado'
  }
};

const defaultEvolutionUrl = (configs.evolution_api_url || '').replace(/\/+$/, '');
const defaultEvolutionKey = (configs.evolution_api_key || '').trim();
let defaultWebhookUrl = (configs.evolution_webhook_url || '').trim();
if (defaultWebhookUrl && !defaultWebhookUrl.includes('/app/')) {
  defaultWebhookUrl = defaultWebhookUrl.replace('/adswhatsinbound', '/app/adswhatsinbound');
}

let instanceName = (input.evolutionapi?.instanceName || '').trim();
if (!instanceName || instanceName === 'loja-undefined' || instanceName === 'loja-null') {
  instanceName = input.id ? `loja-${input.id}` : '';
}

let apiUrl = (input.evolutionapi?.apiUrl || '').trim().replace(/\/+$/, '');
if (!apiUrl) {
  apiUrl = defaultEvolutionUrl;
}

let apikey = (input.evolutionapi?.apikey || '').trim();
if (apikey === '***') apikey = '';
if (!apikey && !isUpdate) {
  apikey = defaultEvolutionKey;
}

let webhookUrl = (input.evolutionapi?.webhookUrl || '').trim();
if (!webhookUrl || !webhookUrl.includes('/app/')) {
  webhookUrl = defaultWebhookUrl;
}

const evolutionapi = {
  instanceName,
  apikey,
  apiUrl,
  webhookUrl
};

const google_ads_keywords = (input.google_ads_keywords || input.config_json?.google_ads_keywords || '').trim();

const config_json = {
  dadosDaLoja,
  evolutionapi,
  google_ads_keywords
};

$input.item.json = {
  valid: true,
  id: input.id || null,
  isUpdate,
  nome,
  whatsapp_loja,
  ativo,
  config_json,
  configs
};

return $input.item;

return {
  json: {
    ok: false,
    message: $input.item.json.errorMessage || 'Operação não permitida.'
  }
};

