const loja = $input.item.json;
const startItem = $('Start').first().json || {};
const configs = startItem.configs || startItem.body?.configs || $('Preparar Dados Loja').first().json.configs || {};
const prepItem = $('Preparar Dados Loja').first().json || {};
const evoDb = loja.config_json?.evolutionapi || {};
const evoPrep = prepItem.config_json?.evolutionapi || {};
const evoInput = {
  ...evoPrep,
  ...evoDb,
  apikey: (evoDb.apikey || evoPrep.apikey || '').trim(),
  token: (evoDb.token || evoPrep.token || '').trim()
};

const defaultEvolutionUrl = (configs.evolution_api_url || '').replace(/\/+$/, '');
const defaultEvolutionKey = (configs.evolution_api_key || '').trim();
let defaultWebhookUrl = (configs.evolution_webhook_url || '').trim();
if (defaultWebhookUrl && !defaultWebhookUrl.includes('/app/')) {
  defaultWebhookUrl = defaultWebhookUrl.replace('/adswhatsinbound', '/app/adswhatsinbound');
}

let instanceName = (evoInput.instanceName || '').trim();
if (!instanceName || instanceName === 'loja-undefined' || instanceName === 'loja-null') {
  instanceName = `loja-${loja.id}`;
}

let apiUrl = (evoInput.apiUrl || '').trim().replace(/\/+$/, '');
if (!apiUrl) {
  apiUrl = defaultEvolutionUrl;
}

let apikey = (evoInput.apikey || '').trim();
if (!apikey) {
  apikey = defaultEvolutionKey;
}

let webhookUrl = (evoInput.webhookUrl || '').trim();
if (!webhookUrl || !webhookUrl.includes('/app/')) {
  webhookUrl = defaultWebhookUrl;
}

const canCheck = Boolean(apiUrl && apikey);

// Geração de token profissional (padrão Evolution API: UUID v4 em maiúsculas de alta entropia)
const generateToken = () => {
  try {
    const c = typeof crypto !== 'undefined' ? crypto : require('crypto');
    if (typeof c.randomUUID === 'function') {
      return c.randomUUID().toUpperCase();
    }
    if (typeof c.randomBytes === 'function') {
      const bytes = c.randomBytes(16);
      bytes[6] = (bytes[6] & 0x0f) | 0x40;
      bytes[8] = (bytes[8] & 0x3f) | 0x80;
      const hex = bytes.toString('hex').toUpperCase();
      return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
    }
  } catch (e) {}
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16).toUpperCase();
  });
};

const rawToken = (evoInput.token || evoInput.instanceToken || '').trim();
const isAmateurToken = !rawToken || rawToken.startsWith('token-') || rawToken === 'token' || rawToken === 'undefined' || rawToken === 'null' || rawToken.length < 16;
const instanceToken = isAmateurToken ? generateToken() : rawToken;
const webhookSecret = (configs.webhook_secret || instanceToken || apikey || '').trim();

const configJson = {
  ...(loja.config_json || {}),
  evolutionapi: {
    instanceName,
    apikey,
    token: instanceToken,
    apiUrl,
    webhookUrl
  }
};

return {
  json: {
    loja_id: loja.id,
    instanceName,
    apiUrl,
    apikey,
    webhookSecret,
    webhookUrl,
    canCheck,
    config_json: configJson,
    createPayload: {
      instanceName,
      qrcode: true,
      integration: 'WHATSAPP-BAILEYS',
      token: instanceToken,
      webhook: {
        enabled: Boolean(webhookUrl),
        url: webhookUrl,
        headers: {
          'x-webhook-secret': webhookSecret
        },
        byEvents: false,
        base64: false,
        events: [
          'MESSAGES_UPSERT',
          'CONNECTION_UPDATE'
        ]
      }
    }
  }
};

const checkRes = $input.item.json;
const prep = $('Preparar Checagem Instância').first().json;

let exists = false;
if (Array.isArray(checkRes)) {
  exists = checkRes.length > 0 && Boolean(checkRes[0]?.name || checkRes[0]?.id || checkRes[0]?.instanceName);
} else if (checkRes?.instance || checkRes?.name || checkRes?.instanceName) {
  exists = true;
} else if (checkRes?.status === 200) {
  exists = true;
}

return {
  json: {
    exists,
    loja_id: prep.loja_id,
    instanceName: prep.instanceName,
    apiUrl: prep.apiUrl,
    apikey: prep.apikey,
    webhookUrl: prep.webhookUrl,
    config_json: prep.config_json,
    createPayload: prep.createPayload
  }
};

