const loja = $input.item.json;
const instanceName = loja.config_json?.evolutionapi?.instanceName || `loja-${loja.id}`;

// Sanitizar config_json para que apikey e token nunca cheguem ao frontend
const safeLoja = { ...loja };
if (safeLoja.config_json) {
  const config = { ...safeLoja.config_json };
  if (config.evolutionapi) {
    const { apikey, token, ...safeEvolution } = config.evolutionapi;
    config.evolutionapi = {
      ...safeEvolution,
      hasApiKey: Boolean(apikey),
      hasToken: Boolean(token)
    };
  }
  safeLoja.config_json = config;
}

return {
  json: {
    ok: true,
    message: 'Loja salva e instância verificada com sucesso!',
    loja: {
      ...safeLoja,
      instanceName
    }
  }
};
